insert into public.faqs(id,question,question_ar,answer,answer_ar,active,display_order) values('e7010000-0000-4000-8000-000000000500','How do I choose a size?','أختار المقاس إزاي؟','Check the size guide on the product page. Development measurements are illustrative until final garment specifications are supplied.','راجع دليل المقاسات في صفحة المنتج. القياسات توضيحية لحد إضافة مواصفات القطع النهائية.',true,0) on conflict(id) do nothing;
insert into public.faqs(id,question,question_ar,answer,answer_ar,active,display_order) values('e7010000-0000-4000-8000-000000000501','Can I place an order?','أقدر أعمل طلب؟','Checkout stays unavailable until the store owner enables it. Card payments are not supported by this installation.','إتمام الطلب غير متاح لحد ما صاحب المتجر يفعله. النسخة الحالية لا تدعم الدفع بالبطاقات.',true,1) on conflict(id) do nothing;
